def find_path(graph, start, goal):
    def dfs(c_node, path, visited, goal):
        # Append the current node to the path
        path.append(c_node)
        visited.add(c_node)
        if c_node == goal:
            # Goal is found, return the path
            return path
        for next_node in graph[c_node]:
            if next_node not in visited:
                new_path = dfs(next_node, path[:], visited, goal)
                if new_path:
                    return new_path
        # If goal is not reached, backtrack
        path.pop()
        visited.remove(c_node)
        return None

    visited = set()
    return dfs(start, [start], visited, goal)
