def find_path(graph, start, goal):
    # Initialize previous nodes, parent predecessors with starts
    previous_nodes = {node: None for node in graph}
    parent_predecessors = {start: None}

    # Initialize nodes in queue and the seen nodes set
    queue = deque([(start, start)])
    seen = set()

    while queue:
        # pop the first node in the queue
        current_node, predecessor = queue.popleft()
        seen.add(current_node)

        # if this node is the goal
        if current_node == goal:
            # re-master previous parents
            while current_node != start: 
                parent_predecessors[current_node] = predecessor
                current_node = previous_nodes[current_node]

            return list(parent_predecessors.values())

        # for each neighborhood
        for neighbor in graph[current_node]:
            if neighbor not in seen:
                previous_nodes[neighbor] = current_node
                queue.append((neighbor, current_node))
                parent_predecessors[neighbor] = current_node

